#include <Keypad.h>
#include <Keyboard.h>

const byte ROWS = 4;
const byte COLS = 4;

char keys[ROWS][COLS] = {
  {'1', '2', '3', 'A'},
  {'4', '5', '6', 'B'},
  {'7', '8', '9', 'C'},
  {'*', '0', '#', 'D'}
};

// Провода R1-R4
byte rowPins[ROWS] = {2, 3, 4, 5};

// Провода C1-C4
byte colPins[COLS] = {6, 7, 8, 9};

Keypad keypad = Keypad(
  makeKeymap(keys),
  rowPins,
  colPins,
  ROWS,
  COLS
);

void setup() {
  Keyboard.begin();
}

void loop() {
  char key = keypad.getKey();

  if (!key) {
    return;
  }

  switch (key) {
    case '0':
    case '1':
    case '2':
    case '3':
    case '4':
    case '5':
    case '6':
    case '7':
    case '8':
    case '9':
      Keyboard.write(key);
      break;

    case 'A':
      // Открыть терминал: Ctrl + Alt + T
      Keyboard.press(KEY_LEFT_CTRL);
      Keyboard.press(KEY_LEFT_ALT);
      Keyboard.press('t');
      delay(100);
      Keyboard.releaseAll();
      break;

    case 'B':
      // Напечатать заранее заданную команду или текст
      Keyboard.print("echo Hello from Arduino");
      Keyboard.write(KEY_RETURN);
      break;

    case 'C':
      // F13 удобно назначать на пользовательские действия в Linux
      Keyboard.press(KEY_F13);
      Keyboard.release(KEY_F13);
      break;

    case 'D':
      // Ещё одна пользовательская клавиша
      Keyboard.press(KEY_F14);
      Keyboard.release(KEY_F14);
      break;

    case '*':
      Keyboard.write(KEY_ESC);
      break;

    case '#':
      Keyboard.write(KEY_RETURN);
      break;
  }

  delay(50);
}
